import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    # Fetch HTML content
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch URL: {e}")

    # Parse HTML and extract tables
    try:
        tree = html.fromstring(response.content)
        tables = tree.xpath('//table')
    except Exception as e:
        # If parsing fails, treat as no table found
        return 0

    if not tables:
        return 0

    # Use pandas to read the first table
    try:
        dfs = pd.read_html(response.text)
    except ValueError:
        # No tables found by pandas
        return 0

    if not dfs:
        return 0

    df = dfs[0]

    if df.empty:
        return 0

    # Store into SQLite database
    try:
        conn = sqlite3.connect(database_name)
        # Replace the table
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.commit()
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(df)

