def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content

    if not content:
        return {}

    if from_encoding is None:
        detected = chardet.detect(content)
        encoding = detected.get('encoding')
        if encoding is None:
            raise ValueError("Unable to detect encoding for non-empty content")
    else:
        encoding = from_encoding

    decoded_text = content.decode(encoding)
    re_encoded_bytes = decoded_text.encode(to_encoding)

    return json.loads(re_encoded_bytes.decode(to_encoding))

import socket
import select
import queue
from datetime import datetime, timedelta

def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    """
    Run a non-blocking echo server that appends the server's current time to received data
    and sends it back to the client, while handling exceptional conditions for each socket.

    Args:
        server_address: The address to bind the server to.
        server_port: The port to bind the server to.
        buffer_size: The buffer size for receiving data.
        run_duration: How long to run the server in seconds.

    Returns:
        str: A status message indicating the server's operation and run duration.
    """
    # Create a server socket
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.bind((server_address, server_port))
    server_socket.listen(5)
    server_socket.setblocking(False)

    # Initialize select inputs
    inputs = [server_socket]
    outputs = []
    message_queues = {}

    # Track start time
    start_time = datetime.now()
    end_time = start_time + timedelta(seconds=run_duration)

    try:
        while datetime.now() < end_time:
            # Calculate remaining time for select timeout
            remaining = (end_time - datetime.now()).total_seconds()
            if remaining <= 0:
                break

            # Use select with a timeout to avoid blocking indefinitely
            readable, writable, exceptional = select.select(inputs, outputs, inputs, min(remaining, 0.1))

            for s in readable:
                if s is server_socket:
                    # Accept new connection
                    try:
                        client_socket, client_address = server_socket.accept()
                        client_socket.setblocking(False)
                        inputs.append(client_socket)
                        message_queues[client_socket] = queue.Queue()
                    except Exception:
                        pass
                else:
                    # Handle data from client
                    try:
                        data = s.recv(buffer_size)
                        if data:
                            # Append current time to received data
                            current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                            response = data + f" [Server time: {current_time}]".encode()
                            message_queues[s].put(response)
                            if s not in outputs:
                                outputs.append(s)
                        else:
                            # Client disconnected
                            if s in outputs:
                                outputs.remove(s)
                            inputs.remove(s)
                            s.close()
                            del message_queues[s]
                    except Exception:
                        # Handle exceptional condition
                        if s in outputs:
                            outputs.remove(s)
                        inputs.remove(s)
                        s.close()
                        if s in message_queues:
                            del message_queues[s]

            for s in writable:
                try:
                    next_msg = message_queues[s].get_nowait()
                    s.send(next_msg)
                except queue.Empty:
                    # Nothing to send, remove from outputs
                    outputs.remove(s)
                except Exception:
                    # Handle exceptional condition
                    if s in outputs:
                        outputs.remove(s)
                    if s in inputs:
                        inputs.remove(s)
                    s.close()
                    if s in message_queues:
                        del message_queues[s]

            for s in exceptional:
                # Handle exceptional condition
                if s in outputs:
                    outputs.remove(s)
                if s in inputs:
                    inputs.remove(s)
                s.close()
                if s in message_queues:
                    del message_queues[s]

        # Clean up remaining connections
        for s in inputs:
            if s is not server_socket:
                s.close()
        for s in outputs:
            s.close()

        actual_duration = (datetime.now() - start_time).total_seconds()
        return f"Server ran for {actual_duration:.2f} seconds"

    finally:
        server_socket.close()

from datetime import datetime
import pytz
import numpy as np
def task_func(time_strings, timezone):
    if len(time_strings) < 2:
        return 0.0

    tz = pytz.timezone(timezone)

    # Parse and convert timestamps to the specified timezone
    converted_times = []
    for ts in time_strings:
        # Parse the timestamp string to a naive datetime object
        # Assuming ISO format or similar that fromisoformat can handle, or use strptime
        # Since the format isn't specified, let's try a common approach.
        # We'll assume the input strings are in ISO format or can be parsed by datetime.fromisoformat
        # If not, we might need a more robust parser. Let's try fromisoformat first.
        try:
            dt = datetime.fromisoformat(ts)
        except ValueError:
            # Try a common format if fromisoformat fails
            try:
                dt = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S")
            except ValueError:
                try:
                    dt = datetime.strptime(ts, "%Y-%m-%dT%H:%M:%S")
                except ValueError:
                    # Last resort: try with microseconds
                    try:
                        dt = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S.%f")
                    except ValueError:
                        try:
                            dt = datetime.strptime(ts, "%Y-%m-%dT%H:%M:%S.%f")
                        except ValueError:
                            raise ValueError(f"Unable to parse timestamp: {ts}")

        # If the datetime is naive, localize it to UTC first, then convert to target timezone
        # Or if it's already aware, convert directly
        if dt.tzinfo is None:
            # Assume naive datetimes are in UTC
            dt = pytz.utc.localize(dt)

        # Convert to the specified timezone
        dt_converted = dt.astimezone(tz)
        converted_times.append(dt_converted)

    # Calculate absolute time differences in seconds between consecutive pairs
    time_diffs = []
    for i in range(len(converted_times) - 1):
        diff = abs((converted_times[i + 1] - converted_times[i]).total_seconds())
        time_diffs.append(diff)

    if not time_diffs:
        return 0.0

    # Calculate the mean using numpy
    mean_diff = np.mean(time_diffs)

    return float(mean_diff)

