import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    """
    Executes a given bash script and returns the CPU and memory usage of the script's process.

    Args:
        script_path: Path to the bash script to execute.
        timeout: Maximum time in seconds to wait for the script to complete.

    Returns:
        A dictionary containing:
        'CPU Usage': The accumulated CPU usage in percentage.
        'Memory Usage': The accumulated memory usage in bytes.
    """
    # Check if the script path exists
    if not os.path.exists(script_path):
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    # Start the subprocess
    try:
        proc = subprocess.Popen(
            ['bash', script_path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
    except Exception as e:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    pid = proc.pid
    total_cpu_usage = 0.0
    total_memory_usage = 0
    start_time = time.time()

    try:
        p = psutil.Process(pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    # Get initial CPU times
    try:
        initial_cpu_times = p.cpu_times()
        initial_cpu_total = initial_cpu_times.user + initial_cpu_times.system
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    # Get initial memory info
    try:
        initial_memory = p.memory_info().rss
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        initial_memory = 0

    last_memory = initial_memory
    last_cpu_total = initial_cpu_total

    while True:
        # Check if process is still running
        try:
            if p.status() == psutil.STATUS_ZOMBIE:
                break
            if not p.is_running():
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break

        # Check timeout
        elapsed = time.time() - start_time
        if elapsed > timeout:
            # Terminate the process
            try:
                p.terminate()
                p.wait(timeout=1)
            except:
                try:
                    p.kill()
                except:
                    pass
            break

        # Get current CPU times
        try:
            current_cpu_times = p.cpu_times()
            current_cpu_total = current_cpu_times.user + current_cpu_times.system
            cpu_increment = current_cpu_total - last_cpu_total
            total_cpu_usage += cpu_increment
            last_cpu_total = current_cpu_total
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break

        # Get current memory info
        try:
            current_memory = p.memory_info().rss
            memory_increment = current_memory - last_memory
            if memory_increment > 0:
                total_memory_usage += memory_increment
            last_memory = current_memory
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break

        # Small sleep to avoid busy waiting
        time.sleep(0.01)

    # Wait for process to complete if it hasn't already
    try:
        proc.wait(timeout=1)
    except:
        try:
            proc.kill()
        except:
            pass

    return {'CPU Usage': total_cpu_usage, 'Memory Usage': total_memory_usage}

import json
import pandas as pd
import numpy as np
from collections import defaultdict

def task_func(input_file="data.json"):
    # Read the JSON file
    with open(input_file, 'r') as f:
        data = json.load(f)

    # Collect numeric values for each key
    key_values = defaultdict(list)

    for record in data:
        for key, value in record.items():
            # Check if the value is numeric (int or float) and not a boolean
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                key_values[key].append(value)

    # Calculate mean and median for each key
    results = {}
    for key, values in key_values.items():
        if len(values) > 0:
            mean_val = np.mean(values)
            median_val = np.median(values)
            results[key] = {'mean': mean_val, 'median': median_val}

    # Create DataFrame
    if results:
        df = pd.DataFrame.from_dict(results, orient='index')
        df.index.name = None
        df = df.sort_index()
    else:
        df = pd.DataFrame(columns=['mean', 'median'])

    return df

